"use client";

/**
 * 損害調査ワークデスク。
 *
 * 損害調査の担当者が、受け付けた事故の連絡を案件として登録し、損害を調べる画面。
 * 事務所のパソコンでも、現場のスマートフォン（375px）でも同じ業務が回るように、
 * 一覧と明細を lg 以上では横に並べ、それより狭いときは行き来する形にしている。
 */

import * as React from "react";
import {
  Button,
  DesktopPageHeader,
  EmptyState,
  FilterChips,
  SectionList,
  SegmentedControl,
  Skeleton,
  Spinner,
  StatGroup,
  VStack,
  ListCard,
  cn,
  type StatisticProps,
} from "@gunjo/ui";
import { IconInbox, IconPlus } from "@tabler/icons-react";

import {
  ACCIDENTS,
  CURRENT_STAFF,
  TODAY,
  daysBetween,
  nextPlannedOn,
  shortDate,
  shortStamp,
  type Accident,
  type DamageAmounts,
  type Stage,
  type SurveyCase,
} from "./data";
import { StageBadge, StalledChip } from "./bits";
import { CaseDetail } from "./case-detail";
import { IntakeDialog } from "./intake-dialog";

type DataState = "ready" | "loading" | "empty";

const STAGE_ORDER: Stage[] = [
  "estimate",
  "counterparty",
  "photos",
  "inquiry",
  "ready",
];

const STAGE_STAT_LABEL: Record<Stage, string> = {
  estimate: "工場の見積待ち",
  counterparty: "相手方の連絡待ち",
  photos: "写真待ち",
  inquiry: "医療照会の回答待ち",
  ready: "査定へ回せる",
};

function initialAmounts(accidents: Accident[]): Record<string, DamageAmounts> {
  const out: Record<string, DamageAmounts> = {};
  for (const a of accidents) {
    for (const c of a.cases) {
      if (c.amounts) out[c.id] = c.amounts;
    }
  }
  return out;
}

export default function LossSurveyPage() {
  const [dataState, setDataState] = React.useState<DataState>("ready");
  const [accidents, setAccidents] = React.useState<Accident[]>(ACCIDENTS);
  const [selectedId, setSelectedId] = React.useState<string>(
    ACCIDENTS[0].cases[0].id
  );
  const [filter, setFilter] = React.useState<string>("all");
  const [mobileView, setMobileView] = React.useState<"list" | "detail">("list");
  const [amounts, setAmounts] = React.useState<Record<string, DamageAmounts>>(
    () => initialAmounts(ACCIDENTS)
  );
  const [selfChecked, setSelfChecked] = React.useState<Record<string, boolean>>(
    {}
  );
  const [forwarded, setForwarded] = React.useState<Record<string, boolean>>({});
  const [intakeOpen, setIntakeOpen] = React.useState(false);

  const showEmpty = dataState === "empty";
  const showLoading = dataState === "loading";

  const shownAccidents = React.useMemo(
    () => (showEmpty ? [] : accidents),
    [showEmpty, accidents]
  );
  const allCases: SurveyCase[] = React.useMemo(
    () => shownAccidents.flatMap((a) => a.cases),
    [shownAccidents]
  );

  const countBy = React.useMemo(() => {
    const map: Record<string, number> = { all: allCases.length };
    for (const s of STAGE_ORDER) {
      map[s] = allCases.filter((c) => c.stage === s).length;
    }
    return map;
  }, [allCases]);

  const stalled3 = allCases.filter(
    (c) => c.stage !== "ready" && daysBetween(c.stalledSince) >= 3
  ).length;
  const stalled7 = allCases.filter(
    (c) => c.stage !== "ready" && daysBetween(c.stalledSince) >= 7
  ).length;

  const selected = allCases.find((c) => c.id === selectedId) ?? allCases[0];
  const selectedAccident = selected
    ? shownAccidents.find((a) => a.id === selected.accidentId)
    : undefined;

  const nextAccidentId = `A-2026-00${4833 + accidents.length - ACCIDENTS.length}`;

  const stats: StatisticProps[] = [
    {
      label: "担当している案件",
      value: `${countBy.all}件`,
      hint: `3日以上 ${stalled3}件`,
      change: stalled7 > 0 ? `7日以上 ${stalled7}件` : "7日以上なし",
      trend: "flat",
      tone: stalled7 > 0 ? "destructive" : "muted",
    },
    ...STAGE_ORDER.map<StatisticProps>((s) => ({
      label: STAGE_STAT_LABEL[s],
      value: `${countBy[s]}件`,
      tone: s === "ready" ? "success" : "muted",
    })),
  ];

  function handleSelect(id: string) {
    setSelectedId(id);
    setMobileView("detail");
  }

  function handleCreate(accident: Accident) {
    setAccidents((prev) => [accident, ...prev]);
    setAmounts((prev) => {
      const next = { ...prev };
      for (const c of accident.cases) if (c.amounts) next[c.id] = c.amounts;
      return next;
    });
    setDataState("ready");
    setSelectedId(accident.cases[0].id);
    setMobileView("detail");
  }

  /* -------------------------------------------------------------- */

  return (
    <main className="mx-auto w-full max-w-[110rem] px-4 pb-20 pt-4 sm:px-6 lg:px-8">
      <DesktopPageHeader
        eyebrow="損害調査部 第二調査課"
        title="損害調査ワークデスク"
        subtitle={`担当 ${CURRENT_STAFF}・${TODAY} 時点`}
        actions={
          <Button size="touch" onClick={() => setIntakeOpen(true)}>
            <IconPlus className="size-4" aria-hidden="true" />
            立件する
          </Button>
        }
      />

      {/* 表示状態の切り替え（この見本で3つの状態を見せるためのもの） */}
      <div className="mt-4 flex flex-col gap-2 rounded-lg border border-dashed border-border p-3 sm:flex-row sm:items-center sm:justify-between">
        <p className="text-xs text-muted-foreground">
          見本用の切り替え。実際の画面では、読み込みと担当0件は自動で切り替わります。
        </p>
        <SegmentedControl
          aria-label="表示する状態を選ぶ"
          options={[
            { value: "ready", label: "通常" },
            { value: "loading", label: "読み込み中" },
            { value: "empty", label: "担当0件" },
          ]}
          value={dataState}
          onValueChange={(v) => {
            setDataState(v as DataState);
            setMobileView("list");
          }}
          size="lg"
          fullWidth={false}
        />
      </div>

      {/* いま何件がどこで止まっているか ------------------------------- */}
      <section aria-labelledby="overview-heading" className="mt-6">
        <h2 id="overview-heading" className="sr-only">
          いま何件がどこで止まっているか
        </h2>
        {showLoading ? (
          <div className="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-6">
            {Array.from({ length: 6 }).map((_, i) => (
              <Skeleton key={i} className="h-[92px] rounded-lg" />
            ))}
          </div>
        ) : (
          <StatGroup items={stats} cols={{ base: 2, md: 3, xl: 6 }} />
        )}
      </section>

      {/* 一覧と明細 -------------------------------------------------- */}
      <div className="mt-6 grid min-w-0 gap-6 lg:grid-cols-[minmax(0,24rem)_minmax(0,1fr)] xl:grid-cols-[minmax(0,27rem)_minmax(0,1fr)]">
        {/* 担当案件の一覧 */}
        <section
          aria-labelledby="case-list-heading"
          className={cn(
            "min-w-0",
            mobileView === "detail" && "hidden lg:block"
          )}
        >
          <h2
            id="case-list-heading"
            className="text-lg font-semibold tracking-tight"
          >
            担当案件
          </h2>
          <p className="mt-1 text-sm text-muted-foreground">
            事故ごとにまとめています。1つの事故から、補償の種類ごとに別々の案件が立ちます。
          </p>

          {showLoading ? (
            <div className="mt-4" role="status" aria-live="polite">
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <Spinner size="sm" />
                担当案件を読み込んでいます
              </div>
              <VStack gap={3} className="mt-4">
                {Array.from({ length: 4 }).map((_, i) => (
                  <div
                    key={i}
                    className="rounded-lg border border-border bg-card p-3"
                  >
                    <div className="flex items-start gap-3">
                      <Skeleton className="h-12 w-12 rounded-md" />
                      <div className="min-w-0 flex-1 space-y-2">
                        <Skeleton className="h-4 w-2/3" />
                        <Skeleton className="h-3 w-1/2" />
                      </div>
                      <Skeleton className="h-5 w-20 rounded-full" />
                    </div>
                  </div>
                ))}
              </VStack>
            </div>
          ) : showEmpty ? (
            <div className="mt-4 rounded-lg border border-border bg-card">
              <EmptyState
                headingLevel={3}
                icon={<IconInbox className="size-8" aria-hidden="true" />}
                title="担当している案件はありません"
                description="受け付けた事故の連絡が回ってくると、ここに案件が並びます。手元にある連絡票から、いま立件することもできます。"
                action={
                  <Button size="touch" onClick={() => setIntakeOpen(true)}>
                    <IconPlus className="size-4" aria-hidden="true" />
                    立件する
                  </Button>
                }
              />
            </div>
          ) : (
            <>
              <div className="mt-4">
                <FilterChips
                  aria-label="止まっている場所でしぼり込む"
                  value={filter}
                  onValueChange={setFilter}
                  items={[
                    { value: "all", label: "すべて", count: countBy.all },
                    ...STAGE_ORDER.map((s) => ({
                      value: s,
                      label: STAGE_STAT_LABEL[s],
                      count: countBy[s],
                      disabled: countBy[s] === 0,
                      disabledReason: "この状態の案件はいまありません",
                    })),
                  ]}
                />
              </div>

              <div className="mt-4">
                <CaseList
                  accidents={shownAccidents}
                  filter={filter}
                  selectedId={selected?.id}
                  onSelect={handleSelect}
                />
              </div>
            </>
          )}
        </section>

        {/* 選んだ案件の調査 */}
        <section
          aria-labelledby="case-detail-heading"
          className={cn("min-w-0", mobileView === "list" && "hidden lg:block")}
        >
          {showLoading ? (
            <div role="status" aria-live="polite" className="space-y-4">
              <h2 id="case-detail-heading" className="sr-only">
                案件の調査
              </h2>
              <Skeleton className="h-24 rounded-lg" />
              <Skeleton className="h-64 rounded-lg" />
              <Skeleton className="h-64 rounded-lg" />
            </div>
          ) : !selected || !selectedAccident ? (
            <div className="rounded-lg border border-border bg-card">
              <h2 id="case-detail-heading" className="sr-only">
                案件の調査
              </h2>
              <EmptyState
                headingLevel={3}
                icon={<IconInbox className="size-8" aria-hidden="true" />}
                title="表示できる案件がありません"
                description="左の一覧で案件を選ぶと、ここに調査の内容が出ます。"
              />
            </div>
          ) : (
            <CaseDetail
              accident={selectedAccident}
              surveyCase={selected}
              siblings={selectedAccident.cases.filter((s) => s.id !== selected.id)}
              amounts={amounts[selected.id]}
              onAmountsChange={(next) =>
                setAmounts((prev) => ({ ...prev, [selected.id]: next }))
              }
              selfChecked={Boolean(selfChecked[selected.id])}
              onSelfCheckedChange={(checked) =>
                setSelfChecked((prev) => ({ ...prev, [selected.id]: checked }))
              }
              forwarded={Boolean(forwarded[selected.id])}
              onForward={() =>
                setForwarded((prev) => ({ ...prev, [selected.id]: true }))
              }
              onSelectCase={setSelectedId}
              onBack={() => setMobileView("list")}
            />
          )}
        </section>
      </div>

      <IntakeDialog
        open={intakeOpen}
        onOpenChange={setIntakeOpen}
        nextAccidentId={nextAccidentId}
        onCreate={handleCreate}
      />
    </main>
  );
}

/* ------------------------------------------------------------------ */
/* 事故ごとにまとめた案件の一覧                                          */
/* ------------------------------------------------------------------ */

function CaseList({
  accidents,
  filter,
  selectedId,
  onSelect,
}: {
  accidents: Accident[];
  filter: string;
  selectedId?: string;
  onSelect: (id: string) => void;
}) {
  const sections = accidents
    .map((a) => {
      const cases =
        filter === "all" ? a.cases : a.cases.filter((c) => c.stage === filter);
      return { accident: a, cases };
    })
    .filter((s) => s.cases.length > 0);

  if (sections.length === 0) {
    return (
      <div className="rounded-lg border border-border bg-card">
        <EmptyState
          headingLevel={3}
          icon={<IconInbox className="size-8" aria-hidden="true" />}
          title="この状態の案件はありません"
          description="しぼり込みを「すべて」に戻すと、担当している案件がすべて出ます。"
        />
      </div>
    );
  }

  return (
    <SectionList
      label="担当案件（事故ごと）"
      sections={sections.map(({ accident: a, cases }) => ({
        key: a.id,
        title: `事故 ${a.id}`,
        sublabel: `${shortStamp(a.occurredAt)}・${a.kind}`,
        meta:
          cases.length === a.cases.length
            ? `${a.cases.length}件`
            : `${cases.length}/${a.cases.length}件`,
        content: (
          <VStack gap={2} className="px-0 py-2">
            {cases.map((c) => {
              const days = daysBetween(c.stalledSince);
              const ready = c.stage === "ready";
              const next = nextPlannedOn(c);
              return (
                <ListCard
                  key={c.id}
                  leading={<StalledChip days={days} ready={ready} />}
                  title={<span className="tabular-nums">{c.id}</span>}
                  description={
                    <>
                      <span className="font-medium text-foreground">
                        {c.coverage}
                      </span>
                      ：{c.subject}
                      <br />
                      契約者 {a.policyholder}
                      {c.waitingOn ? `・待っている先 ${c.waitingOn}` : ""}
                    </>
                  }
                  status={<StageBadge stage={c.stage} />}
                  meta={next ? `次の予定 ${shortDate(next)}` : "次の予定なし"}
                  selected={c.id === selectedId}
                  onSelect={() => onSelect(c.id)}
                />
              );
            })}
          </VStack>
        ),
      }))}
    />
  );
}

"use client";

/**
 * この画面だけで使う小さな部品。
 * @gunjo/ui に相当するものが無かったので自前で組んだものだけを置いている。
 */

import * as React from "react";
import { Badge, cn } from "@gunjo/ui";
import {
  IconBuilding,
  IconCamera,
  IconCircleCheck,
  IconClock,
  IconDeviceMobile,
  IconFileInvoice,
  IconPhone,
  IconStethoscope,
} from "@tabler/icons-react";

import { STAGE, stallLevel, type Stage } from "./data";

const STAGE_ICON: Record<Stage, React.ReactNode> = {
  estimate: <IconFileInvoice />,
  counterparty: <IconPhone />,
  photos: <IconCamera />,
  inquiry: <IconStethoscope />,
  ready: <IconCircleCheck />,
};

/**
 * どこで止まっているかのバッジ。
 * @gunjo/ui の Badge をそのまま使い、色だけでなくアイコンと文字で分かるようにしている。
 */
export function StageBadge({
  stage,
  long = false,
  size = "sm",
}: {
  stage: Stage;
  long?: boolean;
  size?: "sm" | "default" | "lg";
}) {
  const s = STAGE[stage];
  return (
    <Badge variant={s.tone} size={size} icon={STAGE_ICON[stage]}>
      {long ? s.long : s.short}
    </Badge>
  );
}

/**
 * 「止まってから何日たったか」を数字で大きく出す札。
 * 離れた席からでも日数が読めるように、一覧カードの左端の手前に置く。
 * （@gunjo/ui には「経過日数の札」に当たる部品が無いので自前）
 */
export function StalledChip({
  days,
  ready = false,
}: {
  days: number;
  ready?: boolean;
}) {
  if (ready) {
    return (
      <span className="flex h-12 w-12 shrink-0 flex-col items-center justify-center rounded-md bg-success-subtle text-success">
        <IconCircleCheck className="size-6" aria-hidden="true" />
        <span className="sr-only">査定へ回せます。</span>
      </span>
    );
  }
  const level = stallLevel(days);
  const skin =
    level === "late"
      ? "bg-destructive-subtle text-destructive"
      : level === "watch"
        ? "bg-warning-subtle text-warning"
        : "bg-muted text-muted-foreground";
  return (
    <span
      className={cn(
        "flex h-12 w-12 shrink-0 flex-col items-center justify-center rounded-md leading-none",
        skin
      )}
    >
      <span className="sr-only">止まってから</span>
      <span className="text-lg font-bold tabular-nums">{days}</span>
      <span className="mt-0.5 text-[10px] font-medium">日</span>
    </span>
  );
}

/** 停滞日数のひとこと（一覧カードの右下と、明細の見出し下に出す）。 */
export function StallText({ days, ready }: { days: number; ready?: boolean }) {
  if (ready) return <span className="text-success">査定へ回せます</span>;
  const level = stallLevel(days);
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 whitespace-nowrap",
        level === "late" && "font-semibold text-destructive",
        level === "watch" && "text-warning"
      )}
    >
      <IconClock className="size-3.5" aria-hidden="true" />
      止まって {days}日
    </span>
  );
}

/** 記録が現場で打たれたか、事務所で後からまとめられたかの札。 */
export function RecordSourceBadge({ source }: { source: "field" | "desk" }) {
  return source === "field" ? (
    <Badge variant="info" size="sm" icon={<IconDeviceMobile />}>
      現場でその場で記録
    </Badge>
  ) : (
    <Badge variant="secondary" size="sm" icon={<IconBuilding />}>
      事務所であとから記録
    </Badge>
  );
}

"use client";

/**
 * 選んだ案件の調査画面。
 * 基本情報／同じ事故の他の案件／調査の予定と実施／損害額の積み上げ／過失割合／調査の記録／査定へ回す。
 */

import * as React from "react";
import {
  Alert,
  AmountBreakdown,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CheckList,
  Cluster,
  CurrencyInput,
  DistributionBar,
  LimitMonitor,
  ListCard,
  MetadataList,
  RevealSection,
  RouteStops,
  Timeline,
  cn,
  formatCurrency,
  type RouteStopItem,
  type RouteStopStatus,
} from "@gunjo/ui";
import {
  IconAlertTriangle,
  IconArrowBigRightLine,
  IconChevronLeft,
  IconCircleCheck,
  IconCircleDashed,
  IconGavel,
  IconPencil,
} from "@tabler/icons-react";

import {
  TODAY,
  daysBetween,
  shortDate,
  shortStamp,
  totalsOf,
  type Accident,
  type DamageAmounts,
  type SurveyCase,
  type SurveyTask,
} from "./data";
import { RecordSourceBadge, StageBadge, StallText } from "./bits";

/* ------------------------------------------------------------------ */

const TASK_LABELS: Record<RouteStopStatus, string> = {
  pending: "予定",
  current: "実施中",
  completed: "実施済",
  failed: "実施できず",
  delayed: "予定日をすぎて未実施",
};

function toStop(task: SurveyTask): RouteStopItem {
  const overdue = task.status === "planned" && daysBetween(task.plannedOn) > 0;
  const status: RouteStopStatus =
    task.status === "done"
      ? "completed"
      : task.status === "doing"
        ? "current"
        : task.status === "failed"
          ? "failed"
          : overdue
            ? "delayed"
            : "pending";

  const dateLabel = task.doneAt
    ? `実施 ${shortStamp(task.doneAt)}（予定は ${shortDate(task.plannedOn)}）`
    : overdue
      ? `予定 ${shortDate(task.plannedOn)}・${daysBetween(task.plannedOn)}日すぎて未実施`
      : `予定 ${shortDate(task.plannedOn)}・まだ実施していない`;

  return {
    id: task.id,
    title: task.title,
    description: task.detail,
    status,
    dateLabel,
    meta: (
      <Badge variant="outline" size="sm">
        {task.kind}
      </Badge>
    ),
    actions: (
      <span className="text-xs text-muted-foreground">担当 {task.assignee}</span>
    ),
  };
}

/* ------------------------------------------------------------------ */

export interface CaseDetailProps {
  accident: Accident;
  surveyCase: SurveyCase;
  siblings: SurveyCase[];
  amounts?: DamageAmounts;
  onAmountsChange: (next: DamageAmounts) => void;
  selfChecked: boolean;
  onSelfCheckedChange: (checked: boolean) => void;
  forwarded: boolean;
  onForward: () => void;
  onSelectCase: (id: string) => void;
  onBack: () => void;
}

export function CaseDetail({
  accident,
  surveyCase: c,
  siblings,
  amounts,
  onAmountsChange,
  selfChecked,
  onSelfCheckedChange,
  forwarded,
  onForward,
  onSelectCase,
  onBack,
}: CaseDetailProps) {
  const [editAmounts, setEditAmounts] = React.useState(false);
  const stalledDays = daysBetween(c.stalledSince);
  const isReady = c.stage === "ready";

  const totals = amounts ? totalsOf(amounts) : null;
  const missing = c.gate.filter((g) => !g.met);
  const canForward = missing.length === 0 && selfChecked;

  return (
    <div className="min-w-0">
      {/* 見出し ------------------------------------------------------ */}
      <div className="rounded-lg border border-border bg-card p-4">
        <Button
          variant="ghost"
          size="sm"
          className="mb-2 lg:hidden"
          onClick={onBack}
        >
          <IconChevronLeft className="size-4" aria-hidden="true" />
          担当案件の一覧へ
        </Button>

        <p className="text-xs font-semibold text-muted-foreground">
          事故 {accident.id}・{accident.kind}・{shortStamp(accident.occurredAt)}
        </p>
        <h2
          id="case-detail-heading"
          className="mt-1 text-xl font-bold tracking-tight tabular-nums"
        >
          {c.id}
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          {c.coverage}の案件：{c.subject}
        </p>
        <Cluster gap={2} align="center" className="mt-3">
          <StageBadge stage={c.stage} long size="default" />
          <span className="text-sm">
            <StallText days={stalledDays} ready={isReady} />
          </span>
          {c.waitingOn && !isReady && (
            <span className="text-sm text-muted-foreground">
              待っている先：{c.waitingOn}
            </span>
          )}
        </Cluster>
      </div>

      <div className="mt-4 grid gap-4 xl:grid-cols-2">
        {/* 基本情報 -------------------------------------------------- */}
        <Card className="min-w-0">
          <CardHeader>
            <CardTitle as="h3">案件の基本情報</CardTitle>
            <CardDescription>
              受け付けたときの内容。事故そのものの情報は、同じ事故から立った案件で共通です。
            </CardDescription>
          </CardHeader>
          <CardContent>
            <MetadataList
              wrap
              layout="horizontal"
              items={[
                { label: "案件番号", value: c.id },
                { label: "補償の種類", value: `${c.coverage}（${c.subject}）` },
                { label: "事故受付番号", value: accident.id },
                { label: "事故の日時", value: accident.occurredAt },
                { label: "受付日", value: accident.acceptedOn },
                { label: "事故の型", value: accident.kind },
                { label: "場所", value: accident.place },
                { label: "契約者", value: accident.policyholder },
                { label: "証券番号", value: accident.policyNumber },
                {
                  label: "相手方",
                  value: accident.counterparty ?? "なし（自損）",
                },
                { label: "受付時の概要", value: accident.summary },
              ]}
            />
            {c.medicalNote && (
              <Alert variant="info" className="mt-3" title="けがの情報について">
                {c.medicalNote}
              </Alert>
            )}
          </CardContent>
        </Card>

        {/* 同じ事故の案件 -------------------------------------------- */}
        <Card className="min-w-0">
          <CardHeader>
            <CardTitle as="h3">同じ事故から立った案件</CardTitle>
            <CardDescription>
              事故 {accident.id} からは {accident.cases.length} 件の案件が立っています。
              補償の種類ごとに別の案件番号が付き、進み方も別々です。
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-2">
            {accident.cases.map((s) => {
              const days = daysBetween(s.stalledSince);
              const ready = s.stage === "ready";
              const current = s.id === c.id;
              return (
                <ListCard
                  key={s.id}
                  title={
                    <span className="tabular-nums">
                      {s.id}
                      {current && (
                        <span className="ml-2 text-xs font-normal text-muted-foreground">
                          （いま見ている案件）
                        </span>
                      )}
                    </span>
                  }
                  description={`${s.coverage}：${s.subject}`}
                  status={<StageBadge stage={s.stage} />}
                  meta={<StallText days={days} ready={ready} />}
                  selected={current}
                  onSelect={current ? undefined : () => onSelectCase(s.id)}
                  trailing={current ? null : undefined}
                />
              );
            })}
            {siblings.length === 0 && (
              <p className="text-sm text-muted-foreground">
                この事故から立っているのは、この1件だけです。
              </p>
            )}
          </CardContent>
        </Card>

        {/* 調査の予定と実施 ------------------------------------------ */}
        <Card className="min-w-0 xl:col-span-2">
          <CardHeader>
            <CardTitle as="h3">調査の予定と実施</CardTitle>
            <CardDescription>
              上から順に進みます。済んだものには実施した日時が、これからのものには予定日だけが付きます。
            </CardDescription>
          </CardHeader>
          <CardContent>
            <RouteStops
              stops={[...c.tasks]
                .sort((a, b) => a.plannedOn.localeCompare(b.plannedOn))
                .map(toStop)}
              statusLabels={TASK_LABELS}
              currentLabel="いま動いている"
            />
          </CardContent>
        </Card>

        {/* 損害額の積み上げ ------------------------------------------ */}
        <Card className="min-w-0">
          <CardHeader>
            <CardTitle as="h3">損害額の積み上げ</CardTitle>
            <CardDescription>
              工場の見積を、部品代・工賃・塗装代・レッカー費用に分けて足し上げています。
            </CardDescription>
          </CardHeader>
          <CardContent>
            {!amounts || !totals ? (
              <p className="text-sm text-muted-foreground">
                人身の案件なので、車の修理費の積み上げはありません。
                治療にかかった費用は、医療照会の回答が返ってから別の画面で扱います。
              </p>
            ) : (
              <div className="space-y-4">
                <AmountBreakdown
                  lines={[
                    { type: "heading", label: "車の修理（工場の見積）" },
                    {
                      label: "部品代",
                      amount: amounts.parts,
                      note: amounts.estimateFrom
                        ? `見積：${amounts.estimateFrom}`
                        : "見積はまだ届いていない",
                    },
                    { label: "工賃", amount: amounts.labor },
                    { label: "塗装代", amount: amounts.paint },
                    {
                      type: "subtotal",
                      label: "修理費（小計）",
                      amount: totals.repair,
                      note: "全損かどうかは、この小計と時価額を比べて決める",
                    },
                    { type: "heading", label: "付随してかかった費用" },
                    { label: "レッカー費用", amount: amounts.towing },
                  ]}
                  total={{
                    label: "損害額（積み上げ）",
                    amount: totals.claim,
                  }}
                  formula="損害額 ＝ 部品代 ＋ 工賃 ＋ 塗装代 ＋ レッカー費用"
                  formatValue={(v) => formatCurrency(v)}
                />

                <div className="rounded-md border border-border p-3">
                  {amounts.marketValue > 0 ? (
                    <LimitMonitor
                      label="修理費と時価額"
                      value={totals.repair}
                      limit={amounts.marketValue}
                      warnWithin={Math.round(amounts.marketValue * 0.1)}
                      formatValue={(v) => formatCurrency(v)}
                      labels={{
                        ok: "分損",
                        near: "境界",
                        over: "全損",
                        critical: "全損",
                      }}
                      formatReadout={({ over, formatValue }) =>
                        over >= 0
                          ? `修理費が時価額を ${formatValue(Math.abs(over))} 上回っています。全損の扱いになります。`
                          : `時価額まで あと ${formatValue(Math.abs(over))}。修理で処理します。`
                      }
                    />
                  ) : (
                    <p className="text-sm text-muted-foreground">
                      時価額がまだ入っていません。時価額を入れるまで、全損かどうかは判断できません。
                    </p>
                  )}
                  <dl className="mt-3 space-y-1 text-xs text-muted-foreground">
                    <div className="flex flex-wrap gap-x-2">
                      <dt className="font-medium">時価額の根拠</dt>
                      <dd>{amounts.marketValueSource}</dd>
                    </div>
                    {amounts.estimateReceivedOn && (
                      <div className="flex flex-wrap gap-x-2">
                        <dt className="font-medium">見積の受領日</dt>
                        <dd className="tabular-nums">
                          {amounts.estimateReceivedOn}
                        </dd>
                      </div>
                    )}
                  </dl>
                </div>

                {totals.totalLoss && (
                  <Alert
                    variant="warning"
                    icon={<IconAlertTriangle />}
                    title="全損として扱う案件です"
                  >
                    修理費 {formatCurrency(totals.repair)} が時価額{" "}
                    {formatCurrency(amounts.marketValue)} を上回っています。
                    修理ではなく全損の手続きになるため、契約者への説明が要ります。
                  </Alert>
                )}

                <div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setEditAmounts((v) => !v)}
                    aria-expanded={editAmounts}
                  >
                    <IconPencil className="size-4" aria-hidden="true" />
                    {editAmounts ? "内訳を閉じる" : "内訳をなおす"}
                  </Button>
                  <RevealSection
                    open={editAmounts}
                    label="損害額の内訳をなおす"
                    className="mt-3"
                  >
                    <div className="grid gap-3 rounded-md border border-border p-3 sm:grid-cols-2">
                      <CurrencyInput
                        label="部品代"
                        value={amounts.parts}
                        onValueChange={(v) =>
                          onAmountsChange({ ...amounts, parts: v ?? 0 })
                        }
                      />
                      <CurrencyInput
                        label="工賃"
                        value={amounts.labor}
                        onValueChange={(v) =>
                          onAmountsChange({ ...amounts, labor: v ?? 0 })
                        }
                      />
                      <CurrencyInput
                        label="塗装代"
                        value={amounts.paint}
                        onValueChange={(v) =>
                          onAmountsChange({ ...amounts, paint: v ?? 0 })
                        }
                      />
                      <CurrencyInput
                        label="レッカー費用"
                        value={amounts.towing}
                        onValueChange={(v) =>
                          onAmountsChange({ ...amounts, towing: v ?? 0 })
                        }
                      />
                      <CurrencyInput
                        label="その車の時価額"
                        description="修理費がこれを超えると全損の扱いになります"
                        value={amounts.marketValue}
                        onValueChange={(v) =>
                          onAmountsChange({ ...amounts, marketValue: v ?? 0 })
                        }
                      />
                    </div>
                  </RevealSection>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* 過失割合 -------------------------------------------------- */}
        <Card className="min-w-0">
          <CardHeader>
            <CardTitle as="h3">過失割合</CardTitle>
            <CardDescription>
              こちらと相手方の割合、そしてなぜその割合になるのかの根拠。
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <Cluster gap={2} align="center">
              {c.fault.state === "settled" ? (
                <Badge variant="success" icon={<IconCircleCheck />}>
                  確定
                </Badge>
              ) : c.fault.state === "proposed" ? (
                <Badge variant="warning" icon={<IconGavel />}>
                  未確定（協議中）
                </Badge>
              ) : (
                <Badge variant="secondary" icon={<IconCircleDashed />}>
                  未確定（根拠を集めている段階）
                </Badge>
              )}
              {c.fault.state === "settled" && (
                <span className="text-sm text-muted-foreground">
                  {c.fault.settledOn} に {c.fault.settledBy} が確定
                </span>
              )}
            </Cluster>

            {c.fault.ours != null && c.fault.theirs != null ? (
              <div>
                <div className="flex items-baseline justify-between gap-3 text-sm">
                  <span>
                    <span className="text-muted-foreground">当方</span>{" "}
                    <span
                      className={cn(
                        "text-lg font-bold tabular-nums",
                        c.fault.state !== "settled" && "text-muted-foreground"
                      )}
                    >
                      {c.fault.ours}
                    </span>
                  </span>
                  <span className="text-xs text-muted-foreground">
                    {c.fault.state === "settled" ? "確定した割合" : "いま出している案"}
                  </span>
                  <span>
                    <span
                      className={cn(
                        "text-lg font-bold tabular-nums",
                        c.fault.state !== "settled" && "text-muted-foreground"
                      )}
                    >
                      {c.fault.theirs}
                    </span>{" "}
                    <span className="text-muted-foreground">相手方</span>
                  </span>
                </div>
                <div
                  className={cn(
                    "mt-2 rounded-md",
                    c.fault.state !== "settled" &&
                      "border border-dashed border-warning-border p-1 opacity-80"
                  )}
                >
                  <DistributionBar
                    segments={[
                      { label: "当方", value: c.fault.ours, color: "primary" },
                      { label: "相手方", value: c.fault.theirs, color: "accent" },
                    ]}
                    totalLabel="割合"
                    formatValue={(v) => `${v}%`}
                  />
                </div>
                {c.fault.state !== "settled" && (
                  <p className="mt-2 text-xs text-warning">
                    まだ確定していません。破線の枠が付いているあいだは、この割合で支払を進められません。
                  </p>
                )}
              </div>
            ) : (
              <p className="rounded-md border border-dashed border-border p-3 text-sm text-muted-foreground">
                割合の案はまだ出していません。両方の言い分と根拠がそろってから出します。
              </p>
            )}

            {c.fault.basis.length > 0 ? (
              <div>
                <h4 className="mb-2 text-sm font-semibold">
                  この割合になる根拠
                </h4>
                <MetadataList wrap layout="horizontal" items={c.fault.basis} />
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">
                根拠として残せたものはまだありません。
              </p>
            )}

            {c.fault.note && (
              <Alert
                variant={c.fault.state === "settled" ? "success" : "info"}
                title="いまの状況"
              >
                {c.fault.note}
              </Alert>
            )}
          </CardContent>
        </Card>

        {/* 調査の記録 ------------------------------------------------ */}
        <Card className="min-w-0 xl:col-span-2">
          <CardHeader>
            <CardTitle as="h3">調査の記録</CardTitle>
            <CardDescription>
              出来事が起きた順（新しいものが上）。現場でその場で打った記録と、事務所であとからまとめた記録が混ざるので、
              それぞれに「出来事の時刻」と「記録した時刻」の両方を出しています。
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Timeline
              items={[...c.notes]
                .sort((a, b) => b.occurredAt.localeCompare(a.occurredAt))
                .map((n) => {
                  const lag = daysBetween(
                    n.occurredAt.slice(0, 10),
                    n.recordedAt.slice(0, 10)
                  );
                  return {
                    time: `出来事 ${shortStamp(n.occurredAt)}`,
                    title: n.title,
                    variant:
                      n.source === "field" ? ("info" as const) : ("default" as const),
                    descriptionAs: "div" as const,
                    description: (
                      <div className="space-y-1.5">
                        <Cluster gap={2} align="center">
                          <RecordSourceBadge source={n.source} />
                          <span className="text-xs text-muted-foreground">
                            {n.author}
                          </span>
                        </Cluster>
                        <p className="text-sm text-foreground">{n.body}</p>
                        <p className="text-xs tabular-nums text-muted-foreground">
                          記録した時刻 {shortStamp(n.recordedAt)}
                          {lag >= 1
                            ? `（出来事から ${lag}日あとに入力）`
                            : "（出来事と同じ日のうちに入力）"}
                        </p>
                      </div>
                    ),
                  };
                })}
            />
          </CardContent>
        </Card>

        {/* 査定へ回す ------------------------------------------------ */}
        <Card className="min-w-0 xl:col-span-2">
          <CardHeader>
            <CardTitle as="h3">査定へ回す</CardTitle>
            <CardDescription>
              調査が済んだら査定へ回します。足りないものが1つでもあると回せません。
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <CheckList
              items={[
                ...c.gate.map((g) => ({
                  id: g.id,
                  label: g.label,
                  description: g.detail,
                  trailing: (
                    <Badge
                      variant={g.met ? "success" : "warning"}
                      size="sm"
                      icon={g.met ? <IconCircleCheck /> : <IconAlertTriangle />}
                    >
                      {g.status}
                    </Badge>
                  ),
                })),
                {
                  id: "self-check",
                  label: "担当者の自己点検（送る前にひととおり見た）",
                  description:
                    "ここだけは担当者が自分でチェックします。ほかの行はシステムが受領の状況から出しています。",
                  checked: selfChecked,
                },
              ]}
              onCheckedChange={(id, checked) => {
                if (id === "self-check") onSelfCheckedChange(checked);
              }}
            />

            {forwarded ? (
              <Alert
                variant="success"
                icon={<IconCircleCheck />}
                role="status"
                title={`査定へ回しました（${TODAY}）`}
              >
                この案件は査定の担当に移っています。調査側で足すことがあれば、記録に追記してください。
              </Alert>
            ) : canForward ? (
              <Alert
                variant="success"
                icon={<IconCircleCheck />}
                role="status"
                title="必要なものはそろっています"
              >
                足りないものはありません。この案件は査定へ回せます。
              </Alert>
            ) : (
              <Alert
                variant="warning"
                icon={<IconAlertTriangle />}
                role="status"
                title={`査定へ回せません。足りないものが ${
                  missing.length + (selfChecked ? 0 : 1)
                } 件あります`}
              >
                <ul className="mt-1 list-disc space-y-0.5 pl-5 text-sm">
                  {missing.map((g) => (
                    <li key={g.id}>
                      {g.label}
                      <span className="text-muted-foreground">
                        （いまの状態：{g.status}
                        {g.detail ? `。${g.detail}` : ""}）
                      </span>
                    </li>
                  ))}
                  {!selfChecked && (
                    <li>
                      担当者の自己点検
                      <span className="text-muted-foreground">
                        （上のチェックが入っていません）
                      </span>
                    </li>
                  )}
                </ul>
              </Alert>
            )}

            <Button
              variant="primary"
              size="touch"
              className="w-full sm:w-auto"
              disabled={!canForward || forwarded}
              onClick={onForward}
            >
              <IconArrowBigRightLine className="size-4" aria-hidden="true" />
              {forwarded ? "査定へ回し済み" : "査定へ回す"}
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

/**
 * 損害調査ワークデスクの表示データ。
 *
 * 登場する会社名・工場名・人名・車種・地名はすべて架空。
 * 当事者名は法律文書の仮名（甲野・乙川など）を使っている。
 * 人身案件でも傷病の内容そのものはこの画面では扱わない（医療照会の進捗だけを持つ）。
 */

/** 画面の「今日」。SSR とクライアントで日付がずれないよう固定する。 */
export const TODAY = "2026-08-25";

/** ログインしている調査担当。 */
export const CURRENT_STAFF = "都筑（第二調査課）";

/* ------------------------------------------------------------------ */
/* 型                                                                  */
/* ------------------------------------------------------------------ */

/** 補償の種類。1つの事故から、この種類ごとに別々の案件が立つ。 */
export type Coverage = "対物" | "車両" | "人身";

/** いま案件がどこで止まっているか。 */
export type Stage =
  | "estimate" // 工場の見積待ち
  | "counterparty" // 相手方の連絡待ち
  | "photos" // 写真待ち
  | "inquiry" // 医療照会の回答待ち
  | "ready"; // 査定へ回せる

export type SurveyTaskStatus = "done" | "doing" | "planned" | "failed";

/** 調査の1手。予定していることと、済んだことを同じ形で持つ。 */
export interface SurveyTask {
  id: string;
  /** 見積依頼・現場確認・相手方連絡・写真収集・医療照会 */
  kind: string;
  title: string;
  detail?: string;
  status: SurveyTaskStatus;
  /** 予定日 YYYY-MM-DD */
  plannedOn: string;
  /** 実施日時 YYYY-MM-DD HH:MM（未実施なら undefined） */
  doneAt?: string;
  assignee: string;
}

/** 調査の記録。出来事の時刻と、記録した時刻を別々に持つ。 */
export interface SurveyNote {
  id: string;
  /** 出来事が起きた時刻 YYYY-MM-DD HH:MM */
  occurredAt: string;
  /** その記録を打った時刻 YYYY-MM-DD HH:MM */
  recordedAt: string;
  /** field = 現場でその場で打った / desk = 事務所で後からまとめた */
  source: "field" | "desk";
  author: string;
  title: string;
  body: string;
}

/** 損害額の積み上げ。1円単位。 */
export interface DamageAmounts {
  /** 部品代 */
  parts: number;
  /** 工賃 */
  labor: number;
  /** 塗装代 */
  paint: number;
  /** レッカー費用 */
  towing: number;
  /** その車の時価額 */
  marketValue: number;
  /** 時価額の根拠（架空の相場資料名） */
  marketValueSource: string;
  /** 見積を出した工場 */
  estimateFrom?: string;
  /** 見積の受領日 */
  estimateReceivedOn?: string;
}

export interface FaultBasis {
  label: string;
  value: string;
}

/** 過失割合。unset = 根拠もそろっていない / proposed = 案はあるが未確定 / settled = 確定 */
export interface Fault {
  state: "unset" | "proposed" | "settled";
  /** 当方の割合（%） */
  ours?: number;
  /** 相手方の割合（%） */
  theirs?: number;
  settledOn?: string;
  settledBy?: string;
  basis: FaultBasis[];
  note?: string;
}

/** 査定へ回すための持ち物。met=false が1つでもあると回せない。 */
export interface GateItem {
  id: string;
  label: string;
  detail?: string;
  met: boolean;
  /** 受領済 / 未着 / 3件中2件 など */
  status: string;
}

export interface SurveyCase {
  /** 案件番号 */
  id: string;
  accidentId: string;
  coverage: Coverage;
  /** 何についての案件か */
  subject: string;
  stage: Stage;
  /** この段階で止まり始めた日 YYYY-MM-DD */
  stalledSince: string;
  /** 待っている相手（工場名・相手方など） */
  waitingOn?: string;
  amounts?: DamageAmounts;
  fault: Fault;
  tasks: SurveyTask[];
  notes: SurveyNote[];
  gate: GateItem[];
  /** 人身案件で、医療情報をこの画面で扱わないことの注記 */
  medicalNote?: string;
}

export interface Accident {
  /** 事故受付番号 */
  id: string;
  /** 事故日時 YYYY-MM-DD HH:MM */
  occurredAt: string;
  /** 受付日 */
  acceptedOn: string;
  /** 出会い頭・追突 など */
  kind: string;
  /** 事故の場所（架空） */
  place: string;
  /** 契約者 */
  policyholder: string;
  /** 証券番号 */
  policyNumber: string;
  /** 相手方 */
  counterparty?: string;
  summary: string;
  cases: SurveyCase[];
}

/* ------------------------------------------------------------------ */
/* ラベル                                                              */
/* ------------------------------------------------------------------ */

/** 一覧の状態バッジ（短い）と、明細で読ませる長い言い方。 */
export const STAGE: Record<
  Stage,
  { short: string; long: string; tone: "warning" | "info" | "success" }
> = {
