/* ------------------------------------------------------------------ */
/* 日付のヘルパー（すべて固定日基準・SSR で揺れない）                    */
/* ------------------------------------------------------------------ */

function toUtcDay(ymd: string): number {
  const [y, m, d] = ymd.slice(0, 10).split("-").map(Number);
  return Date.UTC(y, (m ?? 1) - 1, d ?? 1);
}

/** from から to までの日数。 */
export function daysBetween(from: string, to: string = TODAY): number {
  return Math.round((toUtcDay(to) - toUtcDay(from)) / 86_400_000);
}

/** 2026-08-21 を 8/21 に。 */
export function shortDate(ymd: string): string {
  const [, m, d] = ymd.slice(0, 10).split("-");
  return `${Number(m)}/${Number(d)}`;
}

/** 2026-08-21 14:20 を 8/21 14:20 に。 */
export function shortStamp(stamp: string): string {
  const [date, time] = stamp.split(" ");
  return time ? `${shortDate(date)} ${time}` : shortDate(date);
}

/** 次に予定している調査の日。無ければ undefined。 */
export function nextPlannedOn(c: SurveyCase): string | undefined {
  return c.tasks
    .filter((t) => t.status === "planned" || t.status === "doing")
    .map((t) => t.plannedOn)
    .sort()[0];
}

/** 停滞日数から、どのくらい急ぐかを出す。 */
export function stallLevel(days: number): "fresh" | "watch" | "late" {
  if (days >= 7) return "late";
  if (days >= 3) return "watch";
  return "fresh";
}

/* ------------------------------------------------------------------ */
/* 積み上げの計算                                                       */
/* ------------------------------------------------------------------ */

export interface DamageTotals {
  /** 部品代 + 工賃 + 塗装代 */
  repair: number;
  /** 修理費 + レッカー費用 */
  claim: number;
  /** 修理費が時価額を超えているか（超えると全損の扱い） */
  totalLoss: boolean;
  /** 時価額との差（正なら超過） */
  gap: number;
}

export function totalsOf(a: DamageAmounts): DamageTotals {
  const repair = a.parts + a.labor + a.paint;
  return {
    repair,
    claim: repair + a.towing,
    totalLoss: repair > a.marketValue,
    gap: repair - a.marketValue,
  };
}

