export const COVERAGE_HELP: Record<Coverage, string> = {
  対物: "相手の車やものの修理。相手方がいる事故で立てる",
  車両: "契約している自分の車の修理",
  人身: "けがの補償。傷病の内容は照会の専用画面で扱う",
};

/** 立件したばかりの案件の中身を作る。 */
export function newCase(
  accidentId: string,
  seq: number,
  coverage: Coverage,
  subject: string
): SurveyCase {
  const id = `T-${accidentId.slice(2)}-${String(seq).padStart(2, "0")}`;
  const isBodily = coverage === "人身";
  return {
    id,
    accidentId,
    coverage,
    subject,
    stage: isBodily ? "inquiry" : "photos",
    stalledSince: TODAY,
    waitingOn: isBodily ? "医療照会の回答" : "写真の到着",
    amounts: isBodily
      ? undefined
      : {
          parts: 0,
          labor: 0,
          paint: 0,
          towing: 0,
          marketValue: 0,
          marketValueSource: "未取得",
        },
    medicalNote: isBodily
      ? "傷病の内容と治療の経過は、この画面では扱わない。医療情報は照会の専用画面でのみ閲覧する。"
      : undefined,
    fault: {
      state: "unset",
      basis: [],
      note: "立件したばかり。根拠を集めてから割合の案を出す。",
    },
    tasks: isBodily
      ? [
          {
            id: `${id}-t1`,
            kind: "医療照会",
            title: "医療照会を出す",
            status: "planned",
            plannedOn: TODAY,
            assignee: CURRENT_STAFF,
          },
        ]
      : [
          {
            id: `${id}-t1`,
            kind: "見積依頼",
            title: "修理工場へ見積を依頼する",
            status: "planned",
            plannedOn: TODAY,
            assignee: CURRENT_STAFF,
          },
          {
            id: `${id}-t2`,
            kind: "写真収集",
            title: "損傷写真を集める（4方向）",
            status: "planned",
            plannedOn: TODAY,
            assignee: CURRENT_STAFF,
          },
          {
            id: `${id}-t3`,
            kind: "相手方連絡",
            title: "相手方へ連絡する",
            status: "planned",
            plannedOn: TODAY,
            assignee: CURRENT_STAFF,
          },
        ],
    notes: [
      {
        id: `${id}-n1`,
        occurredAt: `${TODAY} 09:00`,
        recordedAt: `${TODAY} 09:00`,
        source: "desk",
        author: CURRENT_STAFF,
        title: "受け付けた事故の連絡から立件した",
        body: `${coverage}の案件として立てた。案件番号は ${id}。`,
      },
    ],
    gate: isBodily
      ? [
          { id: "inquiry", label: "医療照会の回答", met: false, status: "未照会" },
          {
            id: "consent",
            label: "けがをした方の連絡先と意向の確認",
            met: false,
            status: "未確認",
          },
          { id: "fault", label: "過失割合の確定", met: false, status: "未確定" },
        ]
      : gate(),
  };
}

"use client";

/**
 * 立件する（受け付けた事故の連絡を、案件として登録する）。
 *
 * 1つの事故から、補償の種類ごとに別々の案件が立つ。
 * どの種類を立てるかを選ぶと、その数だけ案件番号が発番される。
 */

import * as React from "react";
import {
  Alert,
  Badge,
  Button,
  CheckList,
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  Input,
  RevealSection,
  Select,
  Textarea,
  VStack,
} from "@gunjo/ui";
import { IconAlertTriangle, IconPlus } from "@tabler/icons-react";

import {
  COVERAGE_HELP,
  TODAY,
  newCase,
  type Accident,
  type Coverage,
} from "./data";

const COVERAGES: Coverage[] = ["対物", "車両", "人身"];

const SUBJECT: Record<Coverage, string> = {
  対物: "相手方車両の修理",
  車両: "契約車両の修理",
  人身: "けがの補償",
};

const ACCIDENT_KINDS = [
  "出会い頭",
  "追突",
  "進路変更時の接触",
  "駐車場内での接触",
  "右折と直進の衝突",
  "自損（相手方なし）",
];

export interface IntakeDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** 次に発番する事故受付番号。 */
  nextAccidentId: string;
  /** 立件したら、できあがった事故と案件を返す。 */
  onCreate: (accident: Accident) => void;
}

export function IntakeDialog({
  open,
  onOpenChange,
  nextAccidentId,
  onCreate,
}: IntakeDialogProps) {
  const [occurredDate, setOccurredDate] = React.useState(TODAY);
  const [occurredTime, setOccurredTime] = React.useState("09:00");
  const [kind, setKind] = React.useState(ACCIDENT_KINDS[0]);
  const [place, setPlace] = React.useState("");
  const [policyholder, setPolicyholder] = React.useState("");
  const [policyNumber, setPolicyNumber] = React.useState("");
  const [counterparty, setCounterparty] = React.useState("");
  const [summary, setSummary] = React.useState("");
  const [picked, setPicked] = React.useState<Record<Coverage, boolean>>({
    対物: true,
    車両: true,
    人身: false,
  });

  const chosen = COVERAGES.filter((c) => picked[c]);
  const needsCounterparty = picked.対物 || picked.人身;

  const missing: string[] = [];
  if (!policyholder.trim()) missing.push("契約者の氏名");
  if (chosen.length === 0) missing.push("立てる案件（補償の種類を1つ以上）");
  if (needsCounterparty && !counterparty.trim()) {
    missing.push("相手方の氏名（対物または人身を立てるときは必要）");
  }
  const canSubmit = missing.length === 0;

  const previewIds = chosen.map(
    (_, i) => `T-${nextAccidentId.slice(2)}-${String(i + 1).padStart(2, "0")}`
  );

  function handleSubmit() {
    if (!canSubmit) return;
    const accident: Accident = {
      id: nextAccidentId,
      occurredAt: `${occurredDate} ${occurredTime}`,
      acceptedOn: TODAY,
      kind,
      place: place.trim() || "場所は未記入",
      policyholder: policyholder.trim(),
      policyNumber: policyNumber.trim() || "証券番号は未記入",
      counterparty: counterparty.trim() || undefined,
      summary: summary.trim() || "受付時の概要は未記入。",
      cases: chosen.map((coverage, i) =>
        newCase(nextAccidentId, i + 1, coverage, SUBJECT[coverage])
      ),
    };
    onCreate(accident);
    onOpenChange(false);
    setPlace("");
    setPolicyholder("");
    setPolicyNumber("");
    setCounterparty("");
    setSummary("");
    setPicked({ 対物: true, 車両: true, 人身: false });
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[88vh] grid-rows-[auto_minmax(0,1fr)_auto]">
        <DialogHeader>
          <DialogTitle>立件する</DialogTitle>
          <DialogDescription>
            受け付けた事故の連絡を、案件として登録します。1つの事故から、補償の種類ごとに別々の案件が立ちます。
          </DialogDescription>
        </DialogHeader>

        <DialogBody className="px-1">
          <VStack gap={4}>
            <div className="rounded-md border border-border bg-muted/40 px-3 py-2 text-sm">
              <span className="text-muted-foreground">事故受付番号（自動）</span>
              <span className="ml-2 font-medium tabular-nums">{nextAccidentId}</span>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <Input
                label="事故の日"
                type="date"
                value={occurredDate}
                onChange={(e) => setOccurredDate(e.target.value)}
              />
              <Input
                label="事故の時刻"
                type="time"
                value={occurredTime}
                onChange={(e) => setOccurredTime(e.target.value)}
              />
            </div>

            <Select
              label="事故の型"
              value={kind}
              onChange={(e) => setKind(e.target.value)}
            >
              {ACCIDENT_KINDS.map((k) => (
                <option key={k} value={k}>
                  {k}
                </option>
              ))}
            </Select>

            <Input
              label="事故の場所"
              placeholder="例：甲交差点（信号あり）"
              value={place}
              onChange={(e) => setPlace(e.target.value)}
            />

            <div className="grid gap-3 sm:grid-cols-2">
              <Input
                label="契約者"
                placeholder="例：甲野 太郎"
                required
                value={policyholder}
                onChange={(e) => setPolicyholder(e.target.value)}
              />
              <Input
                label="証券番号"
                placeholder="例：SAP-0084-771205"
                value={policyNumber}
                onChange={(e) => setPolicyNumber(e.target.value)}
              />
            </div>

            <Input
              label="相手方"
              description={
                needsCounterparty
                  ? "対物または人身の案件を立てるときは必要です"
                  : "自損の場合は空のままで構いません"
              }
              placeholder="例：乙川 次郎"
              value={counterparty}
              onChange={(e) => setCounterparty(e.target.value)}
            />

            <Textarea
              label="受付時の概要"
              description="通報を受けたときの言葉のまま残してください"
              rows={3}
              value={summary}
              onChange={(e) => setSummary(e.target.value)}
            />

            <div>
              <h3 className="text-sm font-semibold">立てる案件（補償の種類）</h3>
              <p className="mt-1 mb-2 text-xs text-muted-foreground">
                選んだ種類ごとに案件番号が付き、そのあとは別々に進みます。
              </p>
              <CheckList
                items={COVERAGES.map((c) => ({
                  id: c,
                  label: `${c}（${SUBJECT[c]}）`,
                  description: COVERAGE_HELP[c],
                  checked: picked[c],
                }))}
                onCheckedChange={(id, checked) =>
                  setPicked((prev) => ({ ...prev, [id as Coverage]: checked }))
                }
              />
            </div>

            <RevealSection open={chosen.length > 0} label="発番される案件番号">
              <div className="rounded-md border border-border bg-muted/40 p-3">
                <p className="text-sm font-medium">
                  この事故から {chosen.length} 件の案件を立てます
                </p>
                <ul className="mt-2 space-y-1.5">
                  {chosen.map((c, i) => (
                    <li
                      key={c}
                      className="flex flex-wrap items-center gap-2 text-sm"
                    >
                      <span className="font-medium tabular-nums">
                        {previewIds[i]}
                      </span>
                      <Badge variant="secondary" size="sm">
                        {c}
                      </Badge>
                      <span className="text-muted-foreground">
                        {SUBJECT[c]}
                      </span>
                    </li>
                  ))}
                </ul>
                <p className="mt-2 text-xs text-muted-foreground">
                  それぞれの案件は、この先ばらばらに進みます。片方が査定へ回っても、もう片方は調査が続きます。
                </p>
              </div>
            </RevealSection>

            {missing.length > 0 && (
              <Alert
                variant="warning"
                icon={<IconAlertTriangle />}
                role="status"
                title="立件するには、あと少し足りません"
              >
                <ul className="mt-1 list-disc space-y-0.5 pl-5 text-sm">
                  {missing.map((m) => (
                    <li key={m}>{m}</li>
                  ))}
                </ul>
              </Alert>
            )}
          </VStack>
        </DialogBody>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            やめる
          </Button>
          <Button onClick={handleSubmit} disabled={!canSubmit}>
            <IconPlus className="size-4" aria-hidden="true" />
            {chosen.length > 0 ? `${chosen.length}件を立件する` : "立件する"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
